def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= budget:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if not alive_opponents:
        safe_bid = min(budget, DAILY_SALARY * 0.22)
        if hp <= 3 or no_water_days >= 1:
            safe_bid = min(budget, DAILY_SALARY * 0.45)
        return round(max(0.0, safe_bid), 2)

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    danger = 0.0
    if hp <= 2:
        danger += 0.55
    elif hp <= 4:
        danger += 0.3
    if no_water_days >= 2:
        danger += 0.35
    elif no_water_days >= 1:
        danger += 0.18
    if day >= 8:
        danger += 0.08

    pressure = scarcity + danger + 0.06 * urgent_opp + 0.03 * rich_opp

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if supply >= 23 and hp >= 6 and no_water_days == 0:
        base = DAILY_SALARY * 0.18
    elif supply >= 20 and hp >= 5 and no_water_days == 0:
        base = DAILY_SALARY * 0.28
    else:
        base = DAILY_SALARY * (0.34 + 0.42 * min(1.0, pressure))

    if prev_bids:
        if highest_prev >= DAILY_SALARY * 1.6:
            if hp >= 5 and no_water_days == 0:
                target = DAILY_SALARY * 0.3
            else:
                target = DAILY_SALARY * 0.82
        elif highest_prev >= DAILY_SALARY * 1.1:
            target = max(base, min(highest_prev * 0.78, DAILY_SALARY * 0.9))
        else:
            target = max(base, avg_prev + 2.0, highest_prev + 1.25)
    else:
        target = base

    if hp <= 2 or no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.95)
    elif hp <= 4 or no_water_days >= 1:
        target = max(target, DAILY_SALARY * 0.72)

    if budget < DAILY_SALARY * 1.2:
        target = min(target, budget * 0.92)
    elif budget > DAILY_SALARY * 6 and supply <= 18:
        target = max(target, DAILY_SALARY * 0.85)

    target = min(target, budget)
    target = max(0.0, target)
    return round(target, 2)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    base_bid = DAILY_SALARY

    # Adjust base bid based on my health and no_water_days
    if my_status['no_water_days'] > 0:
        base_bid = DAILY_SALARY * 1.5
    elif my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 1.3
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 1.1
    elif my_status['hp'] >= 8:
        base_bid = DAILY_SALARY * 0.9

    num_players_competing = len(alive_opponents) + 1
    water_per_player_if_equal = day_context['supply'] / num_players_competing

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if day_context['day'] == 1 or not yesterday_bids:
        # First day or no opponent trace, rely on supply and health
        if water_per_player_if_equal < WATER_REQ:
            base_bid *= 1.15
        elif water_per_player_if_equal >= WATER_REQ + 2:
            base_bid *= 0.85

        final_bid = max(1.0, min(my_status['budget'], base_bid))
        return final_bid

    highest_prev_bid = max(yesterday_bids)
    average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

    # Reactive bidding based on opponent's previous bids
    if my_status['no_water_days'] > 0 or my_status['hp'] <= 2:
        current_bid = max(base_bid, highest_prev_bid + 5)
    elif highest_prev_bid >= DAILY_SALARY * 1.1:
        current_bid = max(base_bid, average_prev_bid + 2)
    elif highest_prev_bid < DAILY_SALARY * 0.7:
        current_bid = min(base_bid, average_prev_bid + 1, DAILY_SALARY * 0.7)
    else:
        current_bid = max(base_bid, average_prev_bid + 1)

    # End game pressure
    days_left = EPISODE_DAYS - day_context['day']
    if days_left <= 2 and my_status['hp'] <= 3:
        current_bid = max(current_bid, my_status['budget'] * 0.8)

    final_bid = max(1.0, min(my_status['budget'], current_bid))

    return final_bid

